<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\{Article,ArticleEngagementSignal}; use App\Services\NewsPersonalizationService; use Illuminate\Http\Request;
class NewsPersonalizationController extends Controller { public function feed(Request $r,NewsPersonalizationService $svc){return response()->json(['data'=>$svc->feed($r->user())]);} public function signal(Request $r,Article $article){$d=$r->validate(['event'=>'required|in:view,open,like,share,save','weight'=>'nullable|numeric|min:0.1|max:20']);ArticleEngagementSignal::create(['user_id'=>$r->user()?->id,'article_id'=>$article->id,'event'=>$d['event'],'weight'=>$d['weight']??match($d['event']){'view'=>1,'open'=>2,'like'=>4,'share'=>6,'save'=>7}]);return response()->json(['ok'=>true]);} }
